make_a <- function(){b<-read_input("balance_values.csv");order<-c("KL 3 proportion","Age","BMI","Female proportion","Medial JSN grades","Lateral JSN grades","Medial osteophyte grades","Lateral osteophyte grades","Baseline medial JSW","Baseline expected pain");lab<-c("KL 3","Age","BMI","Female","Medial JSN","Lateral JSN","Medial osteophytes","Lateral osteophytes","Medial JSW","Expected pain");b$label<-factor(b$label,levels=rev(order));ggplot(b,aes(value,label,color=stage))+geom_line(aes(group=label),color="#DCE1E8",linewidth=.3)+geom_vline(xintercept=.1,linetype="dashed",color=CFG$grey,linewidth=.3)+geom_point(size=1.25)+scale_color_manual(values=c("Before weighting"=CFG$red,"Overlap weighted"=CFG$blue))+scale_y_discrete(labels=setNames(lab,order))+scale_x_continuous(limits=c(-.02,1.03),breaks=c(0,.5,1),expand=expansion(mult=0))+labs(title="a  Covariate balance",x="Absolute SMD",y=NULL)+base_theme()}
